#[test]
fn int_arithmetic_traps_exactly_when_the_result_leaves_i64() {
    for expression in RUNTIME_TRAPS {
        let source = format!("fn id(x: int) -> int {{ x }}\nprintln(\"{{{expression}}}\")\n");
        for flags in MODES {
            assert_overflow(&run_with(&source, flags), flags, expression);
        }
    }
}

#[test]
fn folded_constant_expressions_trap_at_run_time_like_unfolded_ones() {
    for expression in FOLDED_TRAPS {
        let source = format!("println(\"{{{expression}}}\")\n");
        for flags in MODES {
            assert_overflow(&run_with(&source, flags), flags, expression);
        }
    }
}
